// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.calendarimport timber.log.Timberimport android.content.Contextimport java.text.SimpleDateFormatimport java.util.Dateimport java.util.Locale/** * NOUS — Calendar Engine (Module 14 v1.2 — Step 14.4, CRITICAL). * * REAL implementation of calendar operations using Android's * [CalendarContract] provider. This is NOT a stub — every method * uses REAL ContentResolver APIs via [CalendarReader] / [CalendarWriter]. * * ## Engine Scoping (per strategy v1.1 §"Shift 2") * * CalendarEngine is a **Singleton** (ContentResolver, app-scoped) — * safe to share across activities + coroutines. Contrast with * AlarmEngine (Activity-scoped) and ReminderEngine (Singleton, WorkManager). * * ## Real Android APIs Used (transitively via Reader/Writer) * * | Operation | API | * |-----------|-----| * | getNextEvent | `ContentResolver.query(CalendarContract.Events.CONTENT_URI, ...)` | * | getTodayEvents | `ContentResolver.query` with date range | * | createEvent | `ContentResolver.insert(CalendarContract.Events.CONTENT_URI, ...)` | * | createEventWithReminder | insert Event + insert Reminder (per strategy v1.2 §"Polish 4") | * | updateEvent | `ContentResolver.update(ContentUris.withAppendedId(...), ...)` | * | deleteEvent | `ContentResolver.delete(ContentUris.withAppendedId(...), ...)` | * | getEventReminders | `ContentResolver.query(CalendarContract.Reminders.CONTENT_URI, ...)` | * * ## Privacy * * - Calendar data is NOT encrypted (lives in system provider, shared with *   other apps that have READ_CALENDAR). NOUS never copies calendar data *   into its own DB. * - Never logs event title / description / location (only event IDs + times). * - All operations check permissions via [CalendarPermissionHandler] first; *   missing permissions return [CalendarResult.NeedsPermission] instead of *   crashing with SecurityException. * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Polish 4</a> */class CalendarEngine(    context: Context,    private val reader: CalendarReader = CalendarReader(context),    private val writer: CalendarWriter = CalendarWriter(context),    private val permissions: CalendarPermissionHandler = CalendarPermissionHandler(context),) {    companion object {        private const val TAG = "CalendarEngine"    }    // ═══════════════════════════════════════════════════════════════════════════    // Read Operations (require READ_CALENDAR)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get the next upcoming event.     *     * User-facing: "Mera next event kya hai?" → "Your next event is X at 3 PM."     *     * @return [CalendarResult] with the next [CalendarEvent] (or null if none).     */    fun getNextEvent(): CalendarResult<CalendarEvent?> {        if (!permissions.hasReadAccess()) {            return CalendarResult.NeedsPermission(                permissions = permissions.getMissingReadPermissions(),                spokenMessage = permissions.getMissingReadPermissionsMessage(),            )        }        val event = reader.getNextEvent() ?: return CalendarResult.Success(            data = null,            spokenMessage = "You have no upcoming events.",        )        Timber.tag(TAG).i("Next event: id=${event.id}, start=${event.startMs}.")        return CalendarResult.Success(            data = event,            spokenMessage = "Your next event is '${event.title}' at ${event.displayStartTime}.",        )    }    /**     * Get today's events.     *     * User-facing: "Aaj ke events batao" → "You have 3 events today: ..."     *     * @return [CalendarResult] with list of today's [CalendarEvent].     */    fun getTodayEvents(): CalendarResult<List<CalendarEvent>> {        if (!permissions.hasReadAccess()) {            return CalendarResult.NeedsPermission(                permissions = permissions.getMissingReadPermissions(),                spokenMessage = permissions.getMissingReadPermissionsMessage(),            )        }        val events = reader.getTodayEvents()        Timber.tag(TAG).i("Today's events: ${events.size}.")        val spoken = if (events.isEmpty()) {            "You have no events today."        } else {            val first = events.first()            "You have ${events.size} event${if (events.size == 1) "" else "s"} today. " +                "First: '${first.title}' at ${first.displayStartTime}."        }        return CalendarResult.Success(            data = events,            spokenMessage = spoken,        )    }    /**     * Get events in a time range.     *     * @param startMs range start (epoch ms).     * @param endMs   range end (epoch ms).     * @return [CalendarResult] with list of [CalendarEvent] in range.     */    fun getEventsInRange(startMs: Long, endMs: Long): CalendarResult<List<CalendarEvent>> {        if (!permissions.hasReadAccess()) {            return CalendarResult.NeedsPermission(                permissions = permissions.getMissingReadPermissions(),                spokenMessage = permissions.getMissingReadPermissionsMessage(),            )        }        val events = reader.getEventsInRange(startMs, endMs)        Timber.tag(TAG).i("Events in range (${startMs}..${endMs}): ${events.size}.")        return CalendarResult.Success(            data = events,            spokenMessage = "Found ${events.size} event${if (events.size == 1) "" else "s"} in that range.",        )    }    /**     * Get an event by ID.     *     * @param id event ID.     * @return [CalendarResult] with the [CalendarEvent] (or null if not found).     */    fun getEventById(id: Long): CalendarResult<CalendarEvent?> {        if (!permissions.hasReadAccess()) {            return CalendarResult.NeedsPermission(                permissions = permissions.getMissingReadPermissions(),                spokenMessage = permissions.getMissingReadPermissionsMessage(),            )        }        val event = reader.getEventById(id) ?: return CalendarResult.Success(            data = null,            spokenMessage = "I couldn't find that event.",        )        return CalendarResult.Success(            data = event,            spokenMessage = "Event: '${event.title}' at ${event.displayStartTime}.",        )    }    /**     * Get reminders for an event (per strategy v1.2 §"Polish 4").     *     * @param eventId the event ID.     * @return [CalendarResult] with list of [CalendarReminder].     */    fun getEventReminders(eventId: Long): CalendarResult<List<CalendarReminder>> {        if (!permissions.hasReadAccess()) {            return CalendarResult.NeedsPermission(                permissions = permissions.getMissingReadPermissions(),                spokenMessage = permissions.getMissingReadPermissionsMessage(),            )        }        val reminders = reader.getEventReminders(eventId)        Timber.tag(TAG).i("Reminders for event $eventId: ${reminders.size}.")        return CalendarResult.Success(            data = reminders,            spokenMessage = if (reminders.isEmpty()) "No reminders set for that event."                            else "${reminders.size} reminder${if (reminders.size == 1) "" else "s"} set.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Write Operations (require WRITE_CALENDAR)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Create a calendar event.     *     * User-facing: "Kal 3 baje meeting set karo" → creates event tomorrow at 3 PM.     *     * @param title       event title.     * @param startMs     start time (epoch ms).     * @param endMs       end time (epoch ms).     * @param location    optional location.     * @param description optional description.     * @return [CalendarResult] with the created [CalendarEvent].     */    fun createEvent(        title: String,        startMs: Long,        endMs: Long,        location: String? = null,        description: String? = null,    ): CalendarResult<CalendarEvent> {        if (!permissions.hasWriteCalendarPermission()) {            return CalendarResult.NeedsPermission(                permissions = permissions.getMissingWritePermissions(),                spokenMessage = permissions.getMissingWritePermissionsMessage(),            )        }        val eventId = writer.createEvent(            title = title,            startMs = startMs,            endMs = endMs,            location = location,            description = description,        ) ?: return CalendarResult.Failure(            error = "Failed to insert calendar event.",            spokenMessage = "I couldn't create the calendar event.",        )        val event = CalendarEvent(            id = eventId,            title = title,            startMs = startMs,            endMs = endMs,            location = location,            description = description,        )        return CalendarResult.Success(            data = event,            spokenMessage = "Event '$title' created for ${event.displayStartTime}.",        )    }    /**     * Create a calendar event WITH a reminder (per strategy v1.2 §"Polish 4").     *     * Sets `CalendarContract.Events.HAS_ALARM = 1` and inserts a row into     * `CalendarContract.Reminders` with the given [reminderMinutesBefore].     *     * @param title                   event title.     * @param startMs                 start time (epoch ms).     * @param endMs                   end time (epoch ms).     * @param location                optional location.     * @param description             optional description.     * @param reminderMinutesBefore   reminder minutes before event (default 15).     * @return [CalendarResult] with the created [CalendarEvent] (with [CalendarEvent.hasAlarm]=true).     */    fun createEventWithReminder(        title: String,        startMs: Long,        endMs: Long,        location: String? = null,        description: String? = null,        reminderMinutesBefore: Int = CalendarWriter.DEFAULT_REMINDER_MINUTES,    ): CalendarResult<CalendarEvent> {        if (!permissions.hasWriteCalendarPermission()) {            return CalendarResult.NeedsPermission(                permissions = permissions.getMissingWritePermissions(),                spokenMessage = permissions.getMissingWritePermissionsMessage(),            )        }        val event = writer.createEventWithReminder(            title = title,            startMs = startMs,            endMs = endMs,            location = location,            description = description,            reminderMinutesBefore = reminderMinutesBefore,        ) ?: return CalendarResult.Failure(            error = "Failed to insert calendar event with reminder.",            spokenMessage = "I couldn't create the event with reminder.",        )        return CalendarResult.Success(            data = event,            spokenMessage = "Event '$title' created with a reminder " +                "$reminderMinutesBefore minutes before.",        )    }    /**     * Update an existing event (partial update — only non-null fields are updated).     *     * @param eventId     event ID to update.     * @param title       new title (null = keep existing).     * @param startMs     new start time (null = keep existing).     * @param endMs       new end time (null = keep existing).     * @param location    new location (null = keep existing).     * @param description new description (null = keep existing).     * @return [CalendarResult] with true if updated successfully.     */    fun updateEvent(        eventId: Long,        title: String? = null,        startMs: Long? = null,        endMs: Long? = null,        location: String? = null,        description: String? = null,    ): CalendarResult<Boolean> {        if (!permissions.hasWriteCalendarPermission()) {            return CalendarResult.NeedsPermission(                permissions = permissions.getMissingWritePermissions(),                spokenMessage = permissions.getMissingWritePermissionsMessage(),            )        }        val updated = writer.updateEvent(            eventId = eventId,            title = title,            startMs = startMs,            endMs = endMs,            location = location,            description = description,        )        return if (updated) CalendarResult.Success(            data = true,            spokenMessage = "Event updated.",        ) else CalendarResult.Failure(            error = "Failed to update event.",            spokenMessage = "I couldn't update that event.",        )    }    /**     * Delete an event.     *     * @param eventId event ID to delete.     * @return [CalendarResult] with true if deleted successfully.     */    fun deleteEvent(eventId: Long): CalendarResult<Boolean> {        if (!permissions.hasWriteCalendarPermission()) {            return CalendarResult.NeedsPermission(                permissions = permissions.getMissingWritePermissions(),                spokenMessage = permissions.getMissingWritePermissionsMessage(),            )        }        val deleted = writer.deleteEvent(eventId)        return if (deleted) CalendarResult.Success(            data = true,            spokenMessage = "Event deleted.",        ) else CalendarResult.Failure(            error = "Failed to delete event.",            spokenMessage = "I couldn't delete that event.",        )    }    /**     * Add a reminder to an existing event.     *     * @param eventId       the event ID.     * @param minutesBefore minutes before the event the reminder fires.     * @return [CalendarResult] with true if added successfully.     */    fun addReminder(        eventId: Long,        minutesBefore: Int,    ): CalendarResult<Boolean> {        if (!permissions.hasWriteCalendarPermission()) {            return CalendarResult.NeedsPermission(                permissions = permissions.getMissingWritePermissions(),                spokenMessage = permissions.getMissingWritePermissionsMessage(),            )        }        val added = writer.addReminder(eventId, minutesBefore)        return if (added) CalendarResult.Success(            data = true,            spokenMessage = "Reminder set $minutesBefore minutes before.",        ) else CalendarResult.Failure(            error = "Failed to add reminder.",            spokenMessage = "I couldn't add a reminder to that event.",        )    }    // ═══════════════════════════════════════════════════════════════════════════    // Permission Helpers    // ═══════════════════════════════════════════════════════════════════════════    /** Check if calendar READ permission is granted. */    fun hasReadAccess(): Boolean = permissions.hasReadAccess()    /** Check if calendar WRITE permission is granted. */    fun hasWriteAccess(): Boolean = permissions.hasWriteCalendarPermission()    /** Check if BOTH calendar permissions are granted. */    fun hasFullAccess(): Boolean = permissions.hasFullCalendarAccess()    /** Get the [CalendarPermissionHandler] for UI permission flows. */    fun permissionHandler(): CalendarPermissionHandler = permissions}